def shipWithinDays(weights, days):
    def days_needed(cap):
        used, load = 1, 0
        for w in weights:
            if load + w > cap:
                used += 1
                load = 0
            load += w
        return used

    cap = max(weights)
    while days_needed(cap) > days:
        cap += 1
    return cap

