class Solution {
    public int minDays(int[] bloomDay, int m, int k) {
        if ((long) m * k > bloomDay.length) return -1;
        int[] days = Arrays.stream(bloomDay).distinct().sorted().toArray();
        for (int day : days) if (bouquets(bloomDay, k, day) >= m) return day;
        return -1;
    }

    private int bouquets(int[] bloomDay, int k, int day) {
        int made = 0, run = 0;
        for (int b : bloomDay) {
            run = b <= day ? run + 1 : 0;
            if (run == k) { made++; run = 0; }
        }
        return made;
    }
}

