		made, run := 0, 0
		for _, b := range bloomDay {
			if b <= day {
				run++
			} else {
				run = 0
			}
			if run == k {
				made++
				run = 0
			}
		}
		return made
	}
	days := append([]int(nil), bloomDay...)
	sort.Ints(days)
	for i, day := range days {
		if i > 0 && days[i-1] == day {
			continue // already tried this day
		}
		if bouquets(day) >= m {
			return day
		}
	}
	return -1
